```java
import java.io.*;
import java.util.*;

public class Main {
	static final class FastScanner {
		private final InputStream in;
		private final byte[] buffer = new byte[1 << 16];
		private int ptr = 0, len = 0;
		FastScanner(InputStream is) { in = is; }
		private int read() throws IOException {
			if (ptr >= len) {
				len = in.read(buffer);
				ptr = 0;
				if (len <= 0) return -1;
			}
			return buffer[ptr++];
		}
		int nextInt() throws IOException {
			int c, sgn = 1, x = 0;
			do { c = read(); } while (c <= 32);
			if (c == '-') { sgn = -1; c = read(); }
			while (c > 32) {
				x = x * 10 + (c - '0');
				c = read();
			}
			return x * sgn;
		}
	}

	static final class Fenwick {
		int n;
		long[] bit;
		Fenwick(int n) {
			this.n = n;
			this.bit = new long[n + 1];
		}
		void add(int idx, long delta) {
			for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
		}
		long sumPrefix(int idx) {
			long res = 0;
			for (; idx > 0; idx -= idx & -idx) res += bit[idx];
			return res;
		}
		long sumRange(int l, int r) {
			return sumPrefix(r) - sumPrefix(l - 1);
		}
	}

	public static void main(String[] args) throws Exception {
		FastScanner fs = new FastScanner(System.in);
		int n = fs.nextInt();
		int q = fs.nextInt();
		long[] a = new long[n + 1];
		for (int i = 1; i <= n; i++) a[i] = fs.nextInt();

		Fenwick bitSum = new Fenwick(n);
		Fenwick bitSq  = new Fenwick(n);
		for (int i = 1; i <= n; i++) {
			bitSum.add(i, a[i]);
			bitSq.add(i, a[i] * a[i]);
		}

		StringBuilder sb = new StringBuilder();
		for (int k = 0; k < q; k++) {
			int t = fs.nextInt();
			if (t == 1) {
				int i = fs.nextInt();
				long x = fs.nextInt();
				long delta = x - a[i];
				long deltaSq = x * x - a[i] * a[i];
				bitSum.add(i, delta);
				bitSq.add(i, deltaSq);
				a[i] = x;
			} else {
				int l = fs.nextInt();
				int r = fs.nextInt();
				long S = bitSum.sumRange(l, r);
				long Q = bitSq.sumRange(l, r);
				double m = (double)(r - l + 1);
				double mean = S / m;
				double var = Q / m - mean * mean;
				if (var < 0 && var > -1e-12) var = 0.0; // 数值误差修正
				sb.append(String.format(java.util.Locale.ROOT, "%.6f\n", var));
			}
		}
		System.out.print(sb.toString());
	}
}
